mapper.select:

SELECT CASE
    WHEN NOT EXISTS (SELECT 1 FROM md_icd10_diagnosis directory
        WHERE directory.source_system_code = 'PRIMARY_HIS'
          AND directory.diagnosis_category = #{record.category.code}
          AND directory.source_record_key = #{record.sourceRecordKey}) THEN 0
    WHEN EXISTS (SELECT 1 FROM md_icd10_diagnosis directory
        WHERE directory.source_system_code = 'PRIMARY_HIS'
          AND directory.diagnosis_category = #{record.category.code}
          AND directory.source_record_key = #{record.sourceRecordKey}
          AND (directory.disease_name <> #{record.entry.diseaseName}
            OR directory.source_created_at <> #{record.entry.sourceCreatedAt}
            OR ISNULL(directory.mnemonic_code, '') <> ISNULL(#{record.entry.mnemonicCode,jdbcType=NVARCHAR}, '')
            OR ISNULL(directory.remark, '') <> ISNULL(#{record.entry.remark,jdbcType=NVARCHAR}, '')
            OR ISNULL(directory.source_disease_id, '') <> ISNULL(#{record.entry.sourceDiseaseId,jdbcType=NVARCHAR}, ''))) THEN 1
    ELSE 2 END

mapper.insert:
INSERT INTO md_icd10_diagnosis ( source_system_code, diagnosis_category, source_record_key, disease_code, disease_name, mnemonic_code, remark, source_created_at, source_disease_id, first_seen_batch_id, latest_batch_id, first_seen_at, last_seen_at ) SELECT 'PRIMARY_HIS', source.diagnosis_category, source.source_record_key, source.disease_code, source.disease_name, source.mnemonic_code, source.remark, source.source_created_at, source.source_disease_id, #{batchId}, #{batchId}, SYSUTCDATETIME(), SYSUTCDATETIME() FROM (VALUES
(#{record.category.code}, #{record.sourceRecordKey}, #{record.entry.diseaseCode}, #{record.entry.diseaseName}, #{record.entry.mnemonicCode,jdbcType=NVARCHAR}, #{record.entry.remark,jdbcType=NVARCHAR}, #{record.entry.sourceCreatedAt}, #{record.entry.sourceDiseaseId,jdbcType=NVARCHAR})
) AS source ( diagnosis_category, source_record_key, disease_code, disease_name, mnemonic_code, remark, source_created_at, source_disease_id ) WHERE NOT EXISTS ( SELECT 1 FROM md_icd10_diagnosis directory WITH (UPDLOCK, HOLDLOCK) WHERE directory.source_system_code = 'PRIMARY_HIS' AND directory.diagnosis_category = source.diagnosis_category AND directory.source_record_key = source.source_record_key )
